<template>
  <section class="flex flex-col gap-4">
    <PageTitle :title="pageTitle">
      <FilterTabsNav v-if="!isEditRoute" :items="navigationItems" rounded />
    </PageTitle>
    <div class="flex flex-row flex-wrap items-center justify-between gap-2">
      <GoBackButton
        :subject="isEditRoute ? 'subcontractor company' : 'subcontractor companies'"
        :fallback-to="
          isEditRoute
            ? { name: 'subcontractor-companies-id', params: { id: companyId } }
            : { name: 'subcontractor-companies' }
        "
      />

      <NuxtLink v-if="!isEditRoute" :to="{ name: 'subcontractor-companies-id-edit', params: { id: companyId } }">
        <Button variant="outline" :prepend-icon="Edit2Icon">Edit Company</Button>
      </NuxtLink>
    </div>

    <AppLoader v-if="isLoading && !data" subject="subcontractor company" />
    <AppError v-else-if="error" :error="error" title="Failed to load subcontractor company" />
    <AppEmpty v-else-if="!data" subject="subcontractor company details" />
    <NuxtPage v-else :company="data" />
  </section>
</template>

<script setup lang="ts">
import { getSubcontractorCompanyDetails, type GetSubcontractorCompanyDetailsResponse } from '~/client';
import FilterTabsNav from '~/components/common/FilterTabsNav.vue';
import type { NavigationItem } from '~/types/projects/navigation';
import { Edit2Icon } from 'lucide-vue-next';

definePageMeta({
  roles: ['admin'],
});

const route = useRoute();

const companyId = computed(() => useRoute('subcontractor-companies-id').params.id);

const isEditRoute = computed(() => String(route.name) === 'subcontractor-companies-id-edit');

const pageTitle = computed(() => {
  const name = data.value?.name ?? 'Subcontractor Company';
  return isEditRoute.value ? `${name} - Edit` : name;
});

const { data, error, isLoading } = useQuery({
  key: () => ['subcontractor-company', companyId.value],
  query: (): Promise<GetSubcontractorCompanyDetailsResponse> =>
    getSubcontractorCompanyDetails({
      composable: '$fetch',
      path: { subcontractor_company_id: companyId.value },
    }),
  enabled: () => !!companyId.value,
});

useHead({
  title: () => data.value?.name ?? 'Subcontractor Company',
});

const navigationItems = computed<NavigationItem[]>(() => [
  {
    label: 'Information',
    to: { name: 'subcontractor-companies-id', params: { id: companyId.value } },
    selected: route.name === 'subcontractor-companies-id',
  },
  {
    label: 'Subcontractor canvassers',
    to: { name: 'subcontractor-companies-id-subcanvassers', params: { id: companyId.value } },
    selected: route.name === 'subcontractor-companies-id-subcanvassers',
  },
]);
</script>
